using namespace std;

int main() {
    int rows, cols;
    cin >> rows >> cols;
    vector<vector<long long>> a(rows, vector<long long>(cols));
    for (auto &row : a)
        for (auto &x : row) cin >> x;
    int q;
    cin >> q;
    while (q--) {
        string t;
        cin >> t;
        int R = a.size(), C = a[0].size();
        if (t == "rotate90Clockwise") {
            // old (i, j) moves to (j, R-1-i)
            vector<vector<long long>> b(C, vector<long long>(R));
            for (int i = 0; i < R; i++)
                for (int j = 0; j < C; j++) b[j][R - 1 - i] = a[i][j];
            a = b;
        } else if (t == "swapRows") {
            int i, j;
            cin >> i >> j;
            swap(a[i], a[j]);
        } else if (t == "swapColumns") {
            int i, j;
            cin >> i >> j;
            for (auto &row : a) swap(row[i], row[j]);
        } else if (t == "reverseRow") {
            int i;
            cin >> i;
            reverse(a[i].begin(), a[i].end());
        } else {
            int j;
            cin >> j;
            for (int i = 0; i < R / 2; i++) swap(a[i][j], a[R - 1 - i][j]);
        }
    }
    cout << a.size() << " " << a[0].size() << "\n";
    for (auto &row : a) {
        for (size_t j = 0; j < row.size(); j++) cout << (j ? " " : "") << row[j];
        cout << "\n";
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int rows = Integer.parseInt(st.nextToken()), cols = Integer.parseInt(st.nextToken());
        long[][] a = new long[rows][cols];
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++) a[i][j] = Long.parseLong(st.nextToken());
        int q = Integer.parseInt(st.nextToken());
        while (q-- > 0) {
            String t = st.nextToken();
            int R = a.length, C = a[0].length;
            if (t.equals("rotate90Clockwise")) {
                // old (i, j) moves to (j, R-1-i)
                long[][] b = new long[C][R];
                for (int i = 0; i < R; i++)
                    for (int j = 0; j < C; j++) b[j][R - 1 - i] = a[i][j];
                a = b;
            } else if (t.equals("swapRows")) {
                int i = Integer.parseInt(st.nextToken()), j = Integer.parseInt(st.nextToken());
                long[] tmp = a[i];
                a[i] = a[j];
                a[j] = tmp;
            } else if (t.equals("swapColumns")) {
                int i = Integer.parseInt(st.nextToken()), j = Integer.parseInt(st.nextToken());
                for (long[] row : a) {
                    long tmp = row[i];
                    row[i] = row[j];
                    row[j] = tmp;
                }
            } else if (t.equals("reverseRow")) {
                long[] row = a[Integer.parseInt(st.nextToken())];
                for (int l = 0, r = row.length - 1; l < r; l++, r--) {
                    long tmp = row[l];
                    row[l] = row[r];
                    row[r] = tmp;
                }
            } else {
                int j = Integer.parseInt(st.nextToken());
                for (int i = 0; i < R / 2; i++) {
                    long tmp = a[i][j];
                    a[i][j] = a[R - 1 - i][j];
                    a[R - 1 - i][j] = tmp;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(a.length).append(' ').append(a[0].length).append('\n');
        for (long[] row : a) {
            for (int j = 0; j < row.length; j++) {
                if (j > 0) sb.append(' ');
                sb.append(row[j]);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var rows, cols int
	fmt.Fscan(in, &rows, &cols)
	a := make([][]int, rows)
	for i := range a {
		a[i] = make([]int, cols)
		for j := range a[i] {
			fmt.Fscan(in, &a[i][j])
		}
	}
	var q int
	fmt.Fscan(in, &q)
	for ; q > 0; q-- {
		var t string
		fmt.Fscan(in, &t)
		R, C := len(a), len(a[0])
		switch t {
		case "rotate90Clockwise":
			// old (i, j) moves to (j, R-1-i)
			b := make([][]int, C)
			for j := range b {
				b[j] = make([]int, R)
			}
			for i := 0; i < R; i++ {
				for j := 0; j < C; j++ {
					b[j][R-1-i] = a[i][j]
				}
			}
			a = b
		case "swapRows":
			var i, j int
			fmt.Fscan(in, &i, &j)
			a[i], a[j] = a[j], a[i]
		case "swapColumns":
			var i, j int
			fmt.Fscan(in, &i, &j)
			for _, row := range a {
				row[i], row[j] = row[j], row[i]
			}
		case "reverseRow":
			var i int
			fmt.Fscan(in, &i)
			slices.Reverse(a[i])
		default:
			var j int
			fmt.Fscan(in, &j)
			for i := 0; i < R/2; i++ {
				a[i][j], a[R-1-i][j] = a[R-1-i][j], a[i][j]
			}
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	fmt.Fprintln(w, len(a), len(a[0]))
	for _, row := range a {
		for j, x := range row {
			if j > 0 {
				w.WriteByte(' ')
			}
			fmt.Fprint(w, x)
		}
		w.WriteByte('\n')
	}
}
